    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_SYSTICK1Clk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_FLEXSPIClk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_ADC0Clk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_ADC1Clk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_DAC0Clk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_DAC1Clk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_DAC2Clk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_CTIMER0Clk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_CTIMER1Clk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_CTIMER2Clk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_CTIMER3Clk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_CTIMER4Clk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_SCTClk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_OSTIMERClk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_EWMClk);
    BOARD_BootClockFROHF144M_InitClockModule(kClockModule_WDT0Clk);
