        case kClockModule_DAC1Clk:
            CLOCK_AttachClk(kNONE_to_DAC1);                 /*!< Switch DAC1 to NONE */
            CLOCK_HaltClkDiv(kCLOCK_DivDac1Clk);           /*!< Halt DAC1CLKDIV divider */
            break;
        case kClockModule_DAC2Clk:
            CLOCK_AttachClk(kNONE_to_DAC2);                 /*!< Switch DAC2 to NONE */
            CLOCK_HaltClkDiv(kCLOCK_DivDac2Clk);           /*!< Halt DAC2CLKDIV divider */
