        case kClockModule_CTIMER0Clk:
            CLOCK_AttachClk(kNONE_to_CTIMER0);                 /*!< Switch CTIMER0 to NONE */
            CLOCK_HaltClkDiv(kCLOCK_DivCtimer0Clk);           /*!< Halt CTIMER0CLKDIV divider */
