        case kClockModule_CTIMER1Clk:
            CLOCK_AttachClk(kNONE_to_CTIMER1);                 /*!< Switch CTIMER1 to NONE */
            CLOCK_HaltClkDiv(kCLOCK_DivCtimer1Clk);           /*!< Halt CTIMER1CLKDIV divider */
