        case kClockModule_CTIMER3Clk:
            CLOCK_AttachClk(kNONE_to_CTIMER3);                 /*!< Switch CTIMER3 to NONE */
            CLOCK_HaltClkDiv(kCLOCK_DivCtimer3Clk);           /*!< Halt CTIMER3CLKDIV divider */
            break;
        case kClockModule_CTIMER4Clk:
            CLOCK_AttachClk(kNONE_to_CTIMER4);                 /*!< Switch CTIMER4 to NONE */
